using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.PerfectMatchings;

internal sealed class AlternatingComponentParityDocument : IScribeDocumentDefinition
{
    private const string Prefix =
        "D5/S3/Combinatorics/PerfectMatchings/AlternatingComponentParity.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Every finite component generated by two fixed-point-free matchings has cardinality twice one product orbit.",
        H("Cardinality of alternating matching components"),
        Blocks(
            Paragraph(Text(
                "For permutations s and t with s²=t²=1 and no fixed points, "
                + "Component(s,t,x) is the set of vertices reachable from x by a finite "
                + "sequence of s- or t-steps. The existing orbit-splitting theorem identifies "
                + "this component with two disjoint product orbits. The first matching maps "
                + "one orbit bijectively onto the other, so the component cardinality is twice "
                + "one orbit cardinality, and therefore has even cardinality. Finiteness is used only for Set.ncard.")),
            Describe.Lean(
                DescribeId.Create("component"),
                DeclarationHandle.Create(Prefix + "Component"),
                H("The alternating matching component"),
                StatementSource.FromAuthor(ComponentFormula()),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text(
                    "Component(s,t,x) is exactly the set {y | Connected(s,t,x,y)}. "
                    + "It records the actual reachable component and introduces no graph "
                    + "embedding, orientation or perfect-matching assumption beyond the two "
                    + "permutations used to generate it."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("component-ncard-twice"),
                DeclarationHandle.Create(Prefix + "connected_ncard_eq_two_mul"),
                H("A component is twice one product orbit"),
                StatementSource.FromAuthor(Disp(TwiceFormula())),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text(
                    "The existing component_split theorem supplies a disjoint union of the "
                    + "orbits of s*t through x and s(x), together with the image equality "
                    + "s '' Orbit(x) = Orbit(s(x)). Since s is injective, the two orbit "
                    + "cardinalities agree. The displayed equality is the new cardinality "
                    + "bridge; its factor of two supplies the parity input for the alternating-cycle argument."))),
                DescribeRole.Theorem)),
        [
            DocumentEdge.Dependency.Create(
                GidRef.Create("D5/S3/Combinatorics/PerfectMatchings/InvolutionOrbitSplit"))
        ]));

    private static Formula ComponentFormula() =>
        ForFinite(All("s", Perm(), All("t", Perm(), All("x", X(),
            Equal(Component(S(), T(), F.Id("x")),
                SetOf("y", X(), Call("Connected", S(), T(), F.Id("x"), F.Id("y"))))))));

    private static Formula TwiceFormula() =>
        ForMatchingPairs(All("x", X(),
            Equal(Ncard(Component(S(), T(), F.Id("x"))),
                Multiply(D(2), Ncard(Orbit(F.Id("x")))))));

    private static Formula ForMatchingPairs(Formula body) =>
        ForFinite(All("s", Perm(), All("t", Perm(),
            Imp(And(Involutive(S()), Involutive(T())),
                Imp(And(Free(S()), Free(T())), body)))));

    private static Formula ForFinite(Formula body) =>
        All("X", F.Id("Type"), Imp(Call("Finite", X()), body));

    private static Formula Involutive(Formula f) =>
        All("z", X(), Equal(App(f, App(f, F.Id("z"))), F.Id("z")));

    private static Formula Free(Formula f) =>
        All("z", X(), NotEqual(App(f, F.Id("z")), F.Id("z")));

    private static Formula X() => F.Id("X");
    private static Formula S() => F.Id("s");
    private static Formula T() => F.Id("t");
    private static Formula Perm() => Call("Perm", X());
    private static Formula Component(Formula s, Formula t, Formula x) =>
        Call("Component", s, t, x);
    private static Formula Orbit(Formula x) =>
        Call("RotationOrbit", Multiply(S(), T()), x);
    private static Formula Ncard(Formula set) => Call("ncard", set);
    private static Formula App(Formula f, Formula x) => new Formula.Apply(f, [x]);
    private static Formula All(string name, Formula domain, Formula body) =>
        new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(name), domain, body);
    private static Formula And(Formula a, Formula b) =>
        new Formula.Logic(Parenthesized(a), FormulaLogicOperator.And, Parenthesized(b));
    private static Formula Imp(Formula a, Formula b) =>
        new Formula.Logic(Parenthesized(a), FormulaLogicOperator.Implies, Parenthesized(b));
    private static Formula Parenthesized(Formula body) => Seq(Open, body, Close);
    private static Formula SetOf(string name, Formula domain, Formula body) =>
        Seq(OpenBrace, Sp, F.Id(name), Sp, Colon, Sp, domain, Sp, Mid, Sp,
            Parenthesized(body), Sp, CloseBrace);
}
